parameterdescription.para:
ECC_KEYの希望の長さ Example ecc_keykey;
wc_ecc_init(&key);
WC_WC_RNGrng;
wc_InitRng(&rng);
wc_ecc_make_key(&rng,32,&key);//initialize32byteecckey

鍵作成に使用されるRNG Example ecc_keykey;
intret;
WC_WC_RNGrng;
wc_ecc_init(&key);
wc_InitRng(&rng);
intcurveId=ECC_SECP521R1;
intkeySize=wc_ecc_get_curve_size_from_id(curveId);
ret=wc_ecc_make_key_ex(&rng,keySize,&key,curveId);
if(ret!=MP_OKAY){
//errorhandling
}

simplesect.para:
ECC_INF_E WC_ECC_POINT_IS_AT_INFINITYが1を返す場合に返します。 Example ecc_keykey;
WC_WC_RNGrng;
intcheck_result;
wc_ecc_init(&key);
wc_InitRng(&rng);
wc_ecc_make_key(&rng,32,&key);
check_result=wc_ecc_check_key(&key);

if(check_result==MP_OKAY)
{
//keychecksucceeded
}
else
{
//keycheckfailed
}

parameterdescription.para:
生成された共有秘密鍵を保存する出力バッファへのポインタ Example ecc_keypriv,pub;
WC_WC_RNGrng;
bytesecret[1024];//canhold1024bytesharedsecretkey
word32secretSz=sizeof(secret);
intret;

wc_InitRng(&rng);//initializerng
wc_ecc_init(&priv);//initializekey
wc_ecc_make_key(&rng,32,&priv);//makepublic/privatekeypair
//receivepublickey,andinitialiseintopub
ret=wc_ecc_shared_secret(&priv,&pub,secret,&secretSz);
//generatesecretkey
if(ret!=0){
//errorgeneratingsharedsecretkey
}

共有秘密の出力先。ANSI X9.63からEC-DHに準拠しています。 Example ecc_keykey;
ecc_point*point;
byteshared_secret[];
intsecret_size;
intresult;

point=wc_ecc_new_point();

result=wc_ecc_shared_secret_ex(&key,point,
&shared_secret,&secret_size);

if(result!=MP_OKAY)
{
//Handleerror
}

出力バッファの最大長。メッセージ署名の生成に成功したときに書き込まれたバイトを保存します Example ecc_keykey;
WC_WC_RNGrng;
intret,sigSz;

bytesig[512];//willholdgeneratedsignature
sigSz=sizeof(sig);
bytedigest[]={//initializewithmessagehash};
wc_InitRng(&rng);//initializerng
wc_ecc_init(&key);//initializekey
wc_ecc_make_key(&rng,32,&key);//makepublic/privatekeypair
ret=wc_ecc_sign_hash(digest,sizeof(digest),sig,&sigSz,&key);
if(ret!=0){
//errorgeneratingmessagesignature
}

署名のRコンポーネントの宛先。 Example ecc_keykey;
WC_WC_WC_RNGrng;
intret,sigSz;
mp_intr;//destinationforrcomponentofsignature.
mp_ints;//destinationforscomponentofsignature.

bytesig[512];//willholdgeneratedsignature
sigSz=sizeof(sig);
bytedigest[]={initializewithmessagehash};
wc_InitRng(&rng);//initializerng
wc_ecc_init(&key);//initializekey
mp_init(&r);//initializercomponent
mp_init(&s);//initializescomponent
wc_ecc_make_key(&rng,32,&key);//makepublic/privatekeypair
ret=wc_ecc_sign_hash_ex(digest,sizeof(digest),&rng,&key,&r,&s);

if(ret!=MP_OKAY){
//errorgeneratingmessagesignature
}

検証の結果へのポインタ。1メッセージが正常に認証されたことを示します Example ecc_keykey;
intret,verified=0;

bytesig[1024]{initializewithreceivedsignature};
bytedigest[]={initializewithmessagehash};
//initializekeywithreceivedpublickey
ret=wc_ecc_verify_hash(sig,sizeof(sig),digest,sizeof(digest),
&verified,&key);
if(ret!=0){
//errorperformingverification
}elseif(verified==0){
//thesignatureisinvalid
}

署名の結果、1 ==有効、0 ==無効 Example mp_intr;
mp_ints;
intstat;
bytehash[]={Somehash}
ecc_keykey;

if(wc_ecc_verify_hash_ex(&r,&s,hash,hashlen,&stat,&key)==MP_OKAY)
{
//Checkstat
}

simplesect.para:
int integerがWolfSSLエラーまたは成功状況を示すことを返しました。 Example //initializekeyandperformsecureexchanges
...
wc_ecc_free(&key);

none いいえ返します。 Example ecc_keykey;
//initializekeyandperformsecureexchanges
...

wc_ecc_fp_free();

0 無効な場合は返します。 Example ecc_keykey;
WC_WC_RNGrng;
intis_valid;
wc_ecc_init(&key);
wc_InitRng(&rng);
wc_ecc_make_key(&rng,32,&key);
is_valid=wc_ecc_is_valid_idx(key.idx);
if(is_valid==1)
{
//idxisvalid
}
elseif(is_valid==0)
{
//idxisnotvalid
}

NULL エラー時にNULLを返します。 Example ecc_point*point;
point=wc_ecc_new_point();
if(point==NULL)
{
//Handlepointcreationerror
}
//Dostuffwithpoint

none いいえ返します。 Example ecc_point*point;
point=wc_ecc_new_point();
if(point==NULL)
{
//Handlepointcreationerror
}
//Dostuffwithpoint
wc_ecc_del_point(point);

parameterdescription.para:
コピーするポイント。 Example ecc_point*point;
ecc_point*copied_point;
intcopy_return;

point=wc_ecc_new_point();
copy_return=wc_ecc_copy_point(point,copied_point);
if(copy_return!=MP_OKAY)
{
//Handleerror
}

比較する最初のポイント。 Example ecc_point*point;
ecc_point*point_to_compare;
intcmp_result;

point=wc_ecc_new_point();
point_to_compare=wc_ecc_new_point();
cmp_result=wc_ecc_cmp_point(point,point_to_compare);
if(cmp_result==BAD_FUNC_ARG)
{
//argumentsareinvalid
}
elseif(cmp_result==MP_EQ)
{
//Pointsareequal
}
else
{
//Pointsarenotequal
}

曲線の弾性率 Example ecc_point*base;
ecc_point*destination;
//Initializepoints
base=wc_ecc_new_point();
destination=wc_ecc_new_point();
//Setupotherarguments
mp_intmultiplicand;
mp_intmodulus;
intmap;

ANSI X9.63フォーマット済みキーを保存するバッファへのポインタ Example intret;
bytebuff[1024];
word32buffSz=sizeof(buff);

ecc_keykey;
//initializekey,makekey
ret=wc_ecc_export_x963(&key,buff,&buffSz);
if(ret!=0){
//errorexportingkey
}

出力バッファのサイズ。キーの保存に成功した場合は、出力バッファに書き込まれたバイトを保持します。 Example intret;
bytebuff[1024];
word32buffSz=sizeof(buff);
ecc_keykey;
//initializekey,makekey
ret=wc_ecc_export_x963_ex(&key,buff,&buffSz,1);
if(ret!=0){
//errorexportingkey
}

入力バッファの長さ Example intret;
bytebuff[]={initializewithANSIX9.63formattedkey};

ecc_keypubKey;
wc_ecc_init(&pubKey);

ret=wc_ecc_import_x963(buff,sizeof(buff),&pubKey);
if(ret!=0){
//errorimportingkey
}

公開鍵入力バッファの長さ Example intret;
bytepub[]={initializewithANSIX9.63formattedkey};
bytepriv[]={initializewiththerawprivatekey};

ecc_keykey;
wc_ecc_init(&key);
ret=wc_ecc_import_private_key(priv,sizeof(priv),pub,sizeof(pub),
&key);
if(ret!=0){
//errorimportingkey
}

DERエンコードされたECDSAシグネチャを保存するバッファへのポインタ Example intret;
ecc_keykey;
//initializekey,generateRandS

charr[]={initializewithR};
chars[]={initializewithS};
bytesig[wc_ecc_sig_size(key)];
//signaturesizewillbe2*ECCkeysize+~10bytesforASN.1overhead
word32sigSz=sizeof(sig);
ret=wc_ecc_rs_to_sig(r,s,sig,&sigSz);
if(ret!=0){
//errorconvertingparameterstosignature
}

ASCII hex文字列として秘密鍵を含むバッファへのポインタ Example intret;
ecc_keykey;
wc_ecc_init(&key);

charqx[]={initializewithxcomponentofbasepoint};
charqy[]={initializewithycomponentofbasepoint};
chard[]={initializewithprivatekey};
ret=wc_ecc_import_raw(&key,qx,qy,d,"ECC-256");
if(ret!=0){
//errorinitializingkeywithgiveninputs
}

秘密鍵を保存するバッファへのポインタ Example intret;
ecc_keykey;
//initializekey,makekey

charpriv[ECC_KEY_SIZE];
word32privSz=sizeof(priv);
ret=wc_ecc_export_private_only(&key,priv,&privSz);
if(ret!=0){
//errorexportingprivatekey
}

出力の目的地 Example intcurve_idx;
ecc_point*point;
byteout[];
word32outLen;
wc_ecc_export_point_der(curve_idx,point,out,&outLen);

曲線のインデックス Example bytein[];
word32inLen;
intcurve_idx;
ecc_point*point;
wc_ecc_import_point_der(in,inLen,curve_idx,point);

