ecc_keykey;
//initializekey,makekey
keySz=wc_ecc_size(&key);
if(keySz==0){
//errordeterminingkeysize
}

returns 最大署名サイズ（オクテット） Example intsigSz=wc_ecc_sig_size_calc(32);
if(sigSz==0){
//errordeterminingsigsize
}

0 与えられたキーがNULLの場合に返されます Example intsigSz;
