parameterdescription.para:
これがサーバーであるかクライアントのコンテキストオプションがあるかどうかを示します.req_resp_client、およびreq_resp_server Example ecEncCtx*ctx;
WC_WC_RNGrng;
wc_InitRng(&rng);
ctx=wc_ecc_ctx_new(REQ_RESP_CLIENT,&rng);
if(ctx==NULL){
//errorgeneratingnewecEncCtxobject
}

simplesect.para:
none 戻り値。 Example ecEncCtx*ctx;
WC_WC_RNGrng;
wc_InitRng(&rng);
ctx=wc_ecc_ctx_new(REQ_RESP_CLIENT,&rng);
//dosecurecommunication
...
wc_ecc_ctx_free(&ctx);

parameterdescription.para:
リセットするECENCCTXオブジェクトへのポインタ Example ecEncCtx*ctx;
WC_WC_RNGrng;
wc_InitRng(&rng);
ctx=wc_ecc_ctx_new(REQ_RESP_CLIENT,&rng);
//dosecurecommunication
...
wc_ecc_ctx_reset(&ctx,&rng);
//domoresecurecommunication

使用するKDFアルゴリズム Example ecEncCtx*ctx;
//initializectx
if(wc_ecc_ctx_set_algo(&ctx,ecAES_128_CTR,ecHKDF_SHA256,ecHMAC_SHA256))){
//errorsettinginfo
}

simplesect.para:
NULL ecencctxオブジェクトがNULLの場合、またはECENCCTXの状態がECSRV_INITまたはECCLI_INITでない場合に返されます。後者の2つのケースでは、この機能はそれぞれECSRV_BAD_STATEまたはECCLI_BAD_STATEにECENCCTXの状態を設定します。 Example ecEncCtx*ctx;
WC_WC_RNGrng;
constbyte*salt;
wc_InitRng(&rng);
ctx=wc_ecc_ctx_new(REQ_RESP_CLIENT,&rng);
salt=wc_ecc_ctx_get_own_salt(&ctx);
if(salt==NULL){
//errorgettingsalt
}

parameterdescription.para:
塩を設定するためのecencctxへのポインタ Example ecEncCtx*cliCtx,srvCtx;
WC_WC_RNGrng;
constbyte*cliSalt,srvSalt;
intret;

wc_InitRng(&rng);
cliCtx=wc_ecc_ctx_new(REQ_RESP_CLIENT,&rng);
srvCtx=wc_ecc_ctx_new(REQ_RESP_SERVER,&rng);

cliSalt=wc_ecc_ctx_get_own_salt(&cliCtx);
srvSalt=wc_ecc_ctx_get_own_salt(&srvCtx);
ret=wc_ecc_ctx_set_peer_salt(&cliCtx,srvSalt);

設定する情報を含むバッファへのポインタ Example ecEncCtx*ctx;
byteinfo[]={initializewithinformation};
//initializectx,getsalt,
if(wc_ecc_ctx_set_info(&ctx,info,sizeof(info))){
//errorsettinginfo
}

OUTバッファ内の使用可能なサイズを含むWord32オブジェクトへのポインタ。メッセージの暗号化に成功したら、出力バッファに書き込まれたバイト数を保持します。 Example bytemsg[]={initializewithmsgtoencrypt.Ensurepaddedtoblocksize};
byteout[sizeof(msg)];
word32outSz=sizeof(out);
intret;
ecc_keycli,serv;
//initializecliwithprivatekey
//initializeservwithreceivedpublickey

ecEncCtx*cliCtx,servCtx;
//initializecliCtxandservCtx
//exchangesalts
ret=wc_ecc_encrypt(&cli,&serv,msg,sizeof(msg),out,&outSz,cliCtx);
if(ret!=0){
//errorencryptingmessage
}

オプション：使用するさまざまな暗号化アルゴリズムを指定するECENCCTXオブジェクトへのポインタ Example bytemsg[]={initializewithmsgtoencrypt.Ensurepaddedtoblocksize};
byteout[sizeof(msg)];
word32outSz=sizeof(out);
intret;
ecc_keycli,serv;
//initializecliwithprivatekey
//initializeservwithreceivedpublickey

ecEncCtx*cliCtx,servCtx;
//initializecliCtxandservCtx
//exchangesalts
ret=wc_ecc_encrypt_ex(&cli,&serv,msg,sizeof(msg),out,&outSz,cliCtx,
1);
if(ret!=0){
//errorencryptingmessage
}

OUTバッファ内の使用可能なサイズを含むWord32オブジェクトへのポインタ。暗号文を正常に復号化すると、出力バッファに書き込まれたバイト数を保持します。 Example bytecipher[]={initializewith
ciphertexttodecrypt.Ensurepaddedtoblocksize};
byteplain[sizeof(cipher)];
word32plainSz=sizeof(plain);
intret;
ecc_keycli,serv;
//initializecliwithprivatekey
//initializeservwithreceivedpublickey
ecEncCtx*cliCtx,servCtx;
//initializecliCtxandservCtx
//exchangesalts
ret=wc_ecc_decrypt(&cli,&serv,cipher,sizeof(cipher),
plain,&plainSz,cliCtx);

if(ret!=0){
//errordecryptingmessage
}

ECC_KEYオブジェクトへのポインタ Example intret;
ecc_keyecc;
ecc_nb_ctx_tnb_ctx;

ret=wc_ecc_init(&ecc);
if(ret==0){
ret=wc_ecc_set_nonblock(&ecc,&nb_ctx);
if(ret==0){
do{
ret=wc_ecc_verify_hash_ex(
&r,&s,//r/sasmp_int
hash,hashSz,//computedhashdigest
&verify_res,//verificationresult1=success
&key
);

//TODO:Real-timeworkcanbecalledhere
}while(ret==FP_WOULDBLOCK);
}
wc_ecc_free(&key);
}
